import {types,questions,roles,evidence,calculate} from './model.mjs';
const app=document.querySelector('#app');let step=0;let answers=Array(18).fill(null);let skills=[];let skillAnswered=false;let evidenceIndex=null;let result=null;
const arrow='<span aria-hidden="true">↗</span>';
const typePills=()=>types.map(t=>`<div class="type-pill"><span style="--type-color:${t.color}">${t.code}</span><div>${t.name}<small>${t.verb}</small></div></div>`).join('');
function focusTitle(){requestAnimationFrame(()=>document.querySelector('h1')?.focus({preventScroll:true}));window.scrollTo({top:0,behavior:'instant'});}
function go(hash){if(location.hash===hash)render();else location.hash=hash;}
function home(){app.innerHTML=`<section class="home-hero"><div class="hero-copy"><div class="eyebrow"><span class="mini-line"></span>给还在寻找方向的你</div><h1 tabindex="-1">霍兰德职业<br>兴趣理论测试<span class="title-dot">.</span></h1><p class="hero-subtitle">3～5 分钟，<br class="mobile-break">发现你喜欢做的事。</p><p class="hero-description">从 20 道日常小问题开始，探索你的职业兴趣与自评优势。<br class="desktop-break">适合迷茫时找方向，也适合和朋友一起认识彼此。</p><button class="primary-button" id="start">开始测试 ${arrow}</button><p class="cta-note"><span>20 道题</span><i></i><span>约 3～5 分钟</span><i></i><span>无需注册</span></p></div><div class="hero-visual"><span class="visual-label">每一种兴趣，都有自己的方向。</span><img class="hero-image" src="assets/hero.png" alt="六位平面插画人物通过动手、研究、创作、助人、组织和整理探索自己的兴趣" width="1536" height="1024"><div class="visual-caption"><span>不必成为别人。</span><strong>从你喜欢的开始。</strong><span class="caption-star" aria-hidden="true">✳</span></div></div></section><section class="interest-strip" aria-label="六类职业兴趣"><div class="strip-heading"><span class="eyebrow">SIX WAYS TO EXPLORE</span><h2>六种兴趣，无限可能。</h2></div><div class="type-list">${typePills()}</div></section>`;document.querySelector('#start').onclick=()=>go('#test');}
function quiz(){const answered=step<18?answers[step]!==null:step===18?skillAnswered:evidenceIndex!==null;app.innerHTML=`<section class="quiz-shell"><div class="quiz-top"><button class="text-button" id="back-home">← 返回首页</button><span>第 <strong>${String(step+1).padStart(2,'0')}</strong> / 20 题</span></div><div class="progress-track" role="progressbar" aria-label="答题进度" aria-valuemin="0" aria-valuemax="20" aria-valuenow="${step}"><div style="width:${step/20*100}%"></div></div><div class="quiz-card"><span class="eyebrow">${step<18?'PART 01 · 你喜欢什么':'PART 02 · 你的自评优势'}</span><h1 tabindex="-1">${step<18?questions[step].text:step===18?'哪些事情，你做起来比较顺手？':'你对这些优势的判断，主要来自哪里？'}</h1><p class="question-help">${step<18?'假设条件允许，你有多喜欢做这件事？先不考虑你现在会不会。':step===18?'选择你有实际经历的项目，可多选；暂时没有也没关系。':'选择最符合实际的一项。它不会改变你的兴趣得分。'}</p><fieldset class="answer-list ${step===18?'skill-list':''}"><legend class="sr-only">选择你的回答</legend>${step<18?['很不喜欢','不太喜欢','一般','比较喜欢','非常喜欢'].map((label,i)=>`<label class="answer-option"><input type="radio" name="interest" value="${i}" ${answers[step]===i?'checked':''}><span class="option-number">${i+1}</span><span>${label}</span><span class="option-mark" aria-hidden="true"></span></label>`).join(''):step===18?types.map(t=>`<label class="answer-option"><input type="checkbox" name="skill" value="${t.code}" ${skills.includes(t.code)?'checked':''}><span class="skill-text"><strong>${t.skill}</strong><small>${t.example}</small></span><span class="option-mark" aria-hidden="true"></span></label>`).join('')+`<label class="answer-option none-option"><input type="checkbox" name="none" ${skillAnswered&&!skills.length?'checked':''}><span>暂时不确定，想多尝试一些</span><span class="option-mark" aria-hidden="true"></span></label>`:evidence.map((e,i)=>`<label class="answer-option"><input type="radio" name="evidence" value="${i}" ${evidenceIndex===i?'checked':''}><span>${e.label}</span><span class="option-mark" aria-hidden="true"></span></label>`).join('')}</fieldset><div class="quiz-actions"><button class="text-button" id="previous" ${step===0?'disabled':''}>← 上一题</button><button class="primary-button" id="next" ${answered?'':'disabled'}>${step===19?'查看我的结果':'下一题'} ${arrow}</button></div></div><p class="quiz-reassurance">没有标准答案，选最接近此刻感受的那一个。</p></section>`;
document.querySelector('#back-home').onclick=()=>go('#home');document.querySelector('#previous').onclick=()=>{step--;quiz();focusTitle();};
document.querySelectorAll('input').forEach(input=>input.onchange=()=>{if(step<18)answers[step]=Number(input.value);else if(step===18){if(input.name==='none'){skills=[];skillAnswered=input.checked;}else{skills=[...document.querySelectorAll('input[name="skill"]:checked')].map(x=>x.value);skillAnswered=skills.length>0;}document.querySelectorAll('input[name="skill"]').forEach(x=>x.checked=skills.includes(x.value));document.querySelector('input[name="none"]').checked=skillAnswered&&!skills.length;}else evidenceIndex=Number(input.value);document.querySelector('#next').disabled=step===18?!skillAnswered:false;});
document.querySelector('#next').onclick=()=>{if(step===19){result=calculate(answers);go('#result');}else{step++;quiz();focusTitle();}};
}
function roleArt(role){const col=role.index%5,row=Math.floor(role.index/5);return `<div class="role-art" style="aspect-ratio:150 / 116" role="img" aria-label="${role.name}的平面插画形象"><img src="assets/character-directions.png" alt="" style="height:${1024/116*100}%;left:${-(779+col*150)/150*100}%;top:${-(558+row*147)/116*100}%" width="1536" height="1024"></div>`;}
function results(){if(!result){go('#home');return;}const {ranked,possible,flat}=result;const role=possible.length===1?possible[0]:null;const selected=skills.map(c=>types.find(t=>t.code===c));const interestNames=ranked.filter(t=>t.score>=ranked[1].score).map(t=>t.name).join(' / ');
app.innerHTML=`<section class="results-shell"><div class="result-intro"><span class="eyebrow">YOUR INTEREST ATLAS</span><h1 tabindex="-1">${role?'你的兴趣角色，已解锁。':'你的兴趣，有不止一种可能。'}</h1><p>把这个结果当作起点，去做一次真实的小尝试。</p></div><div class="result-hero"><div>${role?`<span class="role-code">${role.code} · ${[...role.code].map(c=>types.find(t=>t.code===c).name).join(' × ')}</span><h2>${role.name}</h2><p class="role-quote">${role.quote}</p>`:`<span class="role-code">${flat?'六类兴趣得分相同':'同分兴趣 · 保留多种组合'}</span><h2>多元探索倾向</h2><p class="role-quote">${flat?(ranked[0].score<=3?'这些活动暂时没有明显吸引你。换些真实体验，再慢慢寻找。':'这次回答没有显示明确的兴趣高低，暂时不必锁定一个角色。'):'第二名附近出现同分，先看看这些同样可能的方向。'}</p>`}<span class="original-note">基于 RIASEC 的原创兴趣角色</span></div>${role?roleArt(role):'<img class="multi-art" src="assets/hero.png" alt="代表多种职业兴趣的插画人物">'}</div><div class="result-columns"><section class="result-panel"><span class="eyebrow">WHAT YOU ENJOY</span><h2>你喜欢什么</h2><p>${flat?'六类兴趣目前没有拉开差距。':`你本次较突出的兴趣是：${interestNames}。`}</p><div class="score-list">${ranked.map(t=>`<div class="score-row"><div><span><b style="color:${t.color}">${t.code}</b> ${t.name}</span><span>${t.score}<small> / 12</small></span></div><div class="score-track"><div style="width:${t.score/12*100}%;background:${t.color}"></div></div></div>`).join('')}</div><p class="fine-print">分数表示这次回答中的喜好程度，不代表能力或人群排名。</p></section><section class="result-panel strength-panel"><span class="eyebrow">YOUR SELF-REPORTED STRENGTHS</span><h2>你擅长什么 <span class="small-tag">自评优势</span></h2>${selected.length?`<p>你选择的顺手领域：</p><div class="strength-tags">${selected.map(t=>`<span>${t.skill}</span>`).join('')}</div><p class="evidence-note">判断依据：${evidence[evidenceIndex].detail}。</p>${evidenceIndex===3?'<p>这些更适合作为待验证的优势线索。先完成一件小任务，再看看哪些事情确实做得顺手。</p>':'<p>想一想每项优势对应的具体经历：你做了什么？完成了什么？收到了怎样的反馈？</p>'}`:'<p>你还没有选定自评优势，这并不代表没有优势。可以从一次小尝试开始，记录做起来顺手的部分。</p>'}<div class="strength-bottom">喜欢，是愿意投入。<br>擅长，需要在经历中看见。</div></section></div>${role?`<section class="action-panel"><span class="action-icon" aria-hidden="true">↗</span><div><span class="eyebrow">ONE SMALL NEXT STEP</span><h2>给兴趣一次真实的机会。</h2><p>${role.action} 留意：你享受过程吗？哪些部分做得顺手？</p></div></section>`:`<section class="candidate-section"><h2>可以一起探索的角色</h2><p>以下组合都符合本次同分结果；它们不是多个独立的测评结论。</p><div class="candidate-grid">${possible.map(r=>`<article>${roleArt(r)}<span class="eyebrow">${r.code}</span><h3>${r.name}</h3><p>${r.action}</p></article>`).join('')}</div></section>`}<div class="result-actions"><button class="primary-button" id="retry">再测一次 ${arrow}</button><button class="text-button" id="review">修改我的回答</button></div><p class="result-disclaimer">原创探索测试，未经标准化验证。兴趣会随经历变化；结果不限定你的职业选择。</p></section>`;
document.querySelector('#retry').onclick=()=>{answers=Array(18).fill(null);skills=[];skillAnswered=false;evidenceIndex=null;step=0;result=null;go('#test');};document.querySelector('#review').onclick=()=>{step=0;go('#test');};}
function render(){if(location.hash==='#test')quiz();else if(location.hash==='#result')results();else home();focusTitle();}
window.addEventListener('hashchange',render);render();const dialog=document.querySelector('#about-dialog');document.querySelector('#about').onclick=()=>dialog.showModal();document.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
if(document.modelContext?.registerTool){
 const lifetime=new AbortController();
 try{Promise.resolve(document.modelContext.registerTool({
  name:'get_interest_test_state',title:'读取当前职业兴趣测试',
  description:'读取页面当前题目、已完成题数和已生成的兴趣结果；不作答、不开始测试、不修改状态。',
  inputSchema:{type:'object',properties:{},additionalProperties:false},
  annotations:{readOnlyHint:true,untrustedContentHint:false},
  execute(input){
   if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('此工具只接受空对象。');
   return {page:location.hash||'#home',completed:answers.filter(x=>x!==null).length+Number(skillAnswered)+Number(evidenceIndex!==null),question:location.hash==='#test'?{number:step+1,text:step<18?questions[step].text:step===18?'哪些事情，你做起来比较顺手？':'你对这些优势的判断，主要来自哪里？'}:null,result:location.hash==='#result'&&result?{scores:result.scores,roles:result.possible.map(r=>({code:r.code,name:r.name})),selfReportedStrengths:skills.map(c=>types.find(t=>t.code===c).skill)}:null};
  }
 },{signal:lifetime.signal})).catch(()=>{});}catch{}
 window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});
}
